"use client";

import { useEffect, useState } from "react";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Activity } from "lucide-react";

export default function ErpConsolePage() {
  const [events, setEvents] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchEvents();
    const t = setInterval(fetchEvents, 5000);
    return () => clearInterval(t);
  }, []);

  async function fetchEvents() {
    try {
      const res = await fetch("/api/erp-events");
      const json = await res.json();
      if (Array.isArray(json)) setEvents(json);
    } catch (e) {
      console.error("Failed to load erp events", e);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="p-8 space-y-6 bg-slate-50 min-h-screen">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-bold">ERP Console</h2>
          <p className="text-sm text-slate-600">Audit trail of system events: data updates, permission changes, logins, logouts and more.</p>
        </div>
        <Activity className="w-6 h-6 text-slate-400" />
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Recent Events</CardTitle>
          <CardDescription>Latest activity across the ERP.</CardDescription>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Time</TableHead>
                <TableHead>User</TableHead>
                <TableHead>Type</TableHead>
                <TableHead>Target</TableHead>
                <TableHead>Details</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {events.map((ev) => (
                <TableRow key={ev._id ?? ev.id}>
                  <TableCell>{new Date(ev.createdAt).toLocaleString()}</TableCell>
                  <TableCell>{ev.email ?? ev.userId ?? "-"}</TableCell>
                  <TableCell>
                    <Badge variant="outline" className="capitalize">{ev.type}</Badge>
                  </TableCell>
                  <TableCell>{ev.target ?? "-"}</TableCell>
                  <TableCell>
                    <pre className="whitespace-pre-wrap text-xs max-w-xs">{JSON.stringify(ev.details || ev, null, 2)}</pre>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
          {events.length === 0 && !loading && (
            <p className="text-sm text-muted-foreground py-6 text-center">No events yet.</p>
          )}
        </CardContent>
      </Card>
    </div>
  );
}
